package pe.restaurante.service;
import pe.restaurante.dto.*;
import pe.restaurante.entity.*;
import pe.restaurante.repository.*;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.*;
@Service public class OrderService{
 private final RestaurantOrderRepository orders;private final OrderItemRepository items;private final RestaurantProductRepository products;private final DiningTableRepository tables;private final RestaurantUserRepository users;private final RestaurantSaleRepository sales;private final ProductIngredientRepository recipes;private final InventoryItemRepository inventory;private final InventoryMovementRepository movements;
 public OrderService(RestaurantOrderRepository o,OrderItemRepository i,RestaurantProductRepository p,DiningTableRepository t,RestaurantUserRepository u,RestaurantSaleRepository s,ProductIngredientRepository r,InventoryItemRepository inv,InventoryMovementRepository m){orders=o;items=i;products=p;tables=t;users=u;sales=s;recipes=r;inventory=inv;movements=m;}
 @Transactional(readOnly=true) public List<OrderResponse> list(){return orders.findAllByOrderByCreatedAtDesc().stream().map(o->OrderResponse.from(o,items.findAllByOrderId(o.getId()))).toList();}
 @Transactional public OrderResponse create(OrderRequest request,String email){var user=users.findByEmailIgnoreCase(email).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED));var order=new RestaurantOrder();order.setCreatedBy(user);if(request.tableId()!=null){var table=tables.findLockedById(request.tableId()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Mesa no encontrada"));if(!Set.of("AVAILABLE","RESERVED").contains(table.getStatus()))throw new ResponseStatusException(HttpStatus.CONFLICT,"La mesa no está disponible");order.setTableStatusBeforeOrder(table.getStatus());table.setStatus("OCCUPIED");order.setTable(table);}orders.save(order);replaceItems(order,request.items());return OrderResponse.from(order,items.findAllByOrderId(order.getId()));}
 @Transactional public OrderResponse replace(Long id,OrderRequest request){var order=orders.findLockedById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Pedido no encontrado"));if(!Set.of("PENDING","PREPARING").contains(order.getStatus()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Solo puedes modificar pedidos pendientes o en preparación");if(sales.findByOrderId(id).isPresent())throw new ResponseStatusException(HttpStatus.CONFLICT,"El pedido ya tiene una venta asociada");if(!Objects.equals(request.tableId(),order.getTable()==null?null:order.getTable().getId()))throw new ResponseStatusException(HttpStatus.CONFLICT,"No se puede cambiar la mesa de un pedido existente");items.deleteAll(items.findAllByOrderId(id));replaceItems(order,request.items());return OrderResponse.from(order,items.findAllByOrderId(id));}
 @Transactional public OrderResponse changeStatus(Long id,String status,String email){var order=orders.findLockedById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Pedido no encontrado"));boolean valid=switch(order.getStatus()){case "PENDING"->Set.of("PREPARING","CANCELLED").contains(status);case "PREPARING"->Set.of("READY","CANCELLED").contains(status);case "READY"->Set.of("DELIVERED","CANCELLED").contains(status);default->false;};if(!valid)throw new ResponseStatusException(HttpStatus.CONFLICT,"Transición de estado no permitida");if("CANCELLED".equals(status)){if(sales.findByOrderId(id).isPresent())throw new ResponseStatusException(HttpStatus.CONFLICT,"Anula la venta con su flujo auditado");if(order.getTable()!=null)order.getTable().setStatus(order.getTableStatusBeforeOrder()==null?"AVAILABLE":order.getTableStatusBeforeOrder());}if("DELIVERED".equals(status))consumeRecipe(order,email);order.setStatus(status);return OrderResponse.from(order,items.findAllByOrderId(id));}
 private void consumeRecipe(RestaurantOrder order,String email){var user=users.findByEmailIgnoreCase(email).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED));var required=new TreeMap<Long,BigDecimal>();for(var line:items.findAllByOrderId(order.getId()))for(var ingredient:recipes.findAllByProductIdOrderById(line.getProduct().getId()))required.merge(ingredient.getItem().getId(),ingredient.getQuantityPerProduct().multiply(BigDecimal.valueOf(line.getQuantity())),BigDecimal::add);var locked=new LinkedHashMap<Long,InventoryItem>();for(Long itemId:required.keySet())locked.put(itemId,inventory.findLockedById(itemId).orElseThrow(()->new ResponseStatusException(HttpStatus.CONFLICT,"Un insumo de la receta ya no existe")));for(var entry:required.entrySet())if(locked.get(entry.getKey()).getQuantity().compareTo(entry.getValue())<0)throw new ResponseStatusException(HttpStatus.CONFLICT,"Existencias insuficientes para completar el pedido ("+locked.get(entry.getKey()).getName()+")");for(var entry:required.entrySet()){var item=locked.get(entry.getKey());item.setQuantity(item.getQuantity().subtract(entry.getValue()));var movement=new InventoryMovement();movement.setItem(item);movement.setUser(user);movement.setMovementType("OUT");movement.setQuantity(entry.getValue());movement.setNote("Consumo por pedido #"+order.getId());movements.save(movement);}}
 private void replaceItems(RestaurantOrder order,List<OrderRequest.OrderLineRequest> lines){if(lines==null||lines.isEmpty())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"El pedido necesita al menos un producto");var quantities=new LinkedHashMap<Long,Integer>();for(var line:lines)quantities.merge(line.productId(),line.quantity(),Integer::sum);BigDecimal total=BigDecimal.ZERO;var saved=new ArrayList<OrderItem>();for(var entry:quantities.entrySet()){var product=products.findLockedById(entry.getKey()).orElseThrow(()->new ResponseStatusException(HttpStatus.BAD_REQUEST,"Producto inexistente"));if(!product.isAvailable())throw new ResponseStatusException(HttpStatus.CONFLICT,"El producto no está disponible: "+product.getName());var subtotal=product.getPrice().multiply(BigDecimal.valueOf(entry.getValue())).setScale(2,RoundingMode.HALF_UP);var item=new OrderItem();item.setOrder(order);item.setProduct(product);item.setQuantity(entry.getValue());item.setUnitPrice(product.getPrice());item.setSubtotal(subtotal);saved.add(item);total=total.add(subtotal);}items.saveAll(saved);order.setTotal(total.setScale(2,RoundingMode.HALF_UP));}
}
